const trazado = (nombre) => trazados[nombre] || (trazados[nombre] = new Path2D(ICONOS[nombre]));

/* Color del dibujo sobre un fondo: blanco, o tinta si el fondo es claro. */
function colorSobre(fondo) {
  const m = /^#?([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(fondo || "");
  if (!m) return "#ffffff";
  const [r, g, b] = m.slice(1).map((v) => parseInt(v, 16));
  return (0.299 * r + 0.587 * g + 0.114 * b) / 255 > 0.62 ? "#17242e" : "#ffffff";
}

/* Tamaño según lo cerca que se mira: de lejos, un punto; de cerca, la ficha con su icono. */
const radioSimbolo = (zoom) => (zoom >= 17 ? 12 : zoom >= 16 ? 11 : zoom >= 15 ? 10 : zoom >= 14 ? 9 : zoom >= 13 ? 8 : zoom >= 11 ? 6 : 4.5);
const CON_ICONO = 8;      // por debajo de este radio no cabe el dibujo

/* Un punto del mapa dibujado en el lienzo como una ficha con su icono. Es un
   circleMarker de Leaflet al que se le cambia el dibujo: mismo clic y mismo rendimiento
   aunque haya miles. Opciones: forma ("circulo", "cuadrado", "rombo"), icono, fondo,
   realce (color del borde cuando está elegido), giro (grados) y tamano (multiplicador). */
const Simbolo = L.CircleMarker.extend({
  options: { forma: "circulo", icono: null, fondo: "#17242e", realce: null, giro: 0, tamano: 1, apagado: false },
  _project() {
    this._radius = radioSimbolo(this._map.getZoom()) * (this.options.tamano || 1) + (this.options.realce ? 3 : 0);
    L.CircleMarker.prototype._project.call(this);
  },
  setStyle(estilo) {
    L.setOptions(this, estilo);
    return this.redraw();      // vuelve a calcular el tamaño (_project) y repinta el trozo de lienzo
  },
  _updatePath() {
    const lienzo = this._renderer;
    if (!lienzo._drawing || this._empty()) return;
    const ctx = lienzo._ctx, p = this._point, o = this.options, r = this._radius;
    ctx.save();
    ctx.globalAlpha = o.apagado ? 0.55 : 1;
    ctx.translate(p.x, p.y);
    ctx.beginPath();
    if (o.forma === "cuadrado") {
      if (ctx.roundRect) ctx.roundRect(-r, -r, 2 * r, 2 * r, r * 0.32); else ctx.rect(-r, -r, 2 * r, 2 * r);
    } else if (o.forma === "rombo") {
      const d = r * 1.18;
      ctx.moveTo(0, -d); ctx.lineTo(d, 0); ctx.lineTo(0, d); ctx.lineTo(-d, 0); ctx.closePath();
    } else ctx.arc(0, 0, r, 0, 2 * Math.PI);
    ctx.fillStyle = o.fondo;
    ctx.fill();
    // Dos bordes: uno oscuro fino por fuera para que se recorte sobre fotos claras y otro blanco.
    ctx.lineJoin = "round";
    ctx.lineWidth = o.realce ? 5 : 3; ctx.strokeStyle = "rgba(23,36,46,.75)"; ctx.stroke();
    ctx.lineWidth = o.realce ? 3 : 1.6; ctx.strokeStyle = o.realce || "#ffffff"; ctx.stroke();
    if (o.icono && ICONOS[o.icono] && r >= CON_ICONO) {
      const lado = r * (o.forma === "rombo" ? 1.2 : 1.36), k = lado / 24;
      if (o.giro) ctx.rotate((o.giro * Math.PI) / 180);
      ctx.translate(-lado / 2, -lado / 2);
      ctx.scale(k, k);
      ctx.fillStyle = colorSobre(o.fondo);
      ctx.fill(trazado(o.icono));
    }
    ctx.restore();
  },
});
const simbolo = (latlng, opciones) => new Simbolo(latlng, opciones);

/* Los mismos símbolos como SVG, para el panel de capas, las fichas y los resultados. */
const SVG_NS = "http://www.w3.org/2000/svg";
function nodoSVG(etiqueta, atributos) {
  const n = document.createElementNS(SVG_NS, etiqueta);
  for (const [k, v] of Object.entries(atributos)) n.setAttribute(k, v);
  return n;
}
function simboloSVG(icono, fondo, forma, lado = 20) {
  const svg = nodoSVG("svg", { viewBox: "0 0 32 32", width: lado, height: lado, class: "simbolo", "aria-hidden": "true" });
  const borde = { fill: fondo, stroke: "#ffffff", "stroke-width": 2, "paint-order": "stroke" };
  const sombra = { fill: "none", stroke: "rgba(23,36,46,.75)", "stroke-width": 4 };
  const figura = (extra) => (forma === "cuadrado" ? nodoSVG("rect", Object.assign({ x: 3, y: 3, width: 26, height: 26, rx: 5 }, extra))
    : forma === "rombo" ? nodoSVG("path", Object.assign({ d: "M16 1.5 30.5 16 16 30.5 1.5 16Z", "stroke-linejoin": "round" }, extra))
    : nodoSVG("circle", Object.assign({ cx: 16, cy: 16, r: 13 }, extra)));
  svg.append(figura(sombra), figura(borde));
  if (ICONOS[icono]) {
    const k = forma === "rombo" ? 0.68 : 0.78;
    svg.append(nodoSVG("path", { d: ICONOS[icono], fill: colorSobre(fondo), transform: `translate(${16 - 12 * k} ${16 - 12 * k}) scale(${k})` }));
  }
  return svg;
}
/* Solo el dibujo, en el color del texto: para botones. */
function iconoSVG(nombre, lado = 18) {
  const svg = nodoSVG("svg", { viewBox: "0 0 24 24", width: lado, height: lado, "aria-hidden": "true" });
  svg.append(nodoSVG("path", { d: ICONOS[nombre], fill: "currentColor" }));
  return svg;
}
/* Chincheta de un marcador propio (va en el mapa como HTML: se puede arrastrar). */
function chinchetaHTML(icono, fondo, abierta) {
  const k = 0.62, sobre = colorSobre(fondo);
  return `<svg viewBox="0 0 32 42" width="32" height="42" class="chincheta${abierta ? " abierta" : ""}" aria-hidden="true">` +
    `<path d="M16 1.5C8 1.5 1.5 8 1.5 16c0 10.4 12.3 22.600 14.5 24.6C18.2 38.6 30.5 26.4 30.5 16 30.500 8 24 1.500 16 1.500Z" fill="${fondo}" stroke="#ffffff" stroke-width="2.4"/>` +
    `<path d="${ICONOS[icono] || ""}" fill="${sobre}" transform="translate(${16 - 12 * k} ${15.5 - 12 * k}) scale(${k})"/></svg>`;
}

/* Rellena los huecos de símbolo que hay escritos en la página: <span data-icono="…">. */
function ponerSimbolos(raiz) {
  for (const hueco of (raiz || document).querySelectorAll("[data-icono]")) {
    if (hueco.firstChild) continue;
    hueco.append(hueco.dataset.fondo ? simboloSVG(hueco.dataset.icono, hueco.dataset.fondo, hueco.dataset.forma, +hueco.dataset.lado || 20) : iconoSVG(hueco.dataset.icono, +hueco.dataset.lado || 18));
  }
}

/* ---------- Modo claro y oscuro ----------
   El tema se decide antes de pintar nada (en la cabecera de la página) para que no
   parpadee; aquí solo se cambia cuando se pulsa el botón. */
function temaActual() { return document.documentElement.dataset.tema === "oscuro" ? "oscuro" : "claro"; }
function ponerTema(tema, recordar) {
  document.documentElement.dataset.tema = tema;
  if (recordar) { try { localStorage.setItem("osintmaps.tema.v1", JSON.stringify(tema)); } catch { /* sin almacenamiento */ } }
  const boton = document.getElementById("tema");
  if (boton) {
    boton.setAttribute("aria-pressed", String(tema === "oscuro"));
    boton.title = tema === "oscuro" ? "Cambiar a modo claro" : "Cambiar a modo oscuro";
    boton.setAttribute("aria-label", boton.title);
    boton.replaceChildren(iconoSVG(tema === "oscuro" ? "sol" : "luna", 20));
  }
}
